-- MySQL 8 starter schema. Financial values are integer cents; timestamps are UTC.
CREATE DATABASE IF NOT EXISTS untaxpoint CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE untaxpoint;
CREATE TABLE users (id VARCHAR(64) PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, wallet_cents BIGINT NOT NULL DEFAULT 0, status VARCHAR(24) NOT NULL DEFAULT 'active', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE events (id VARCHAR(64) PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, address VARCHAR(400), latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, radius_meters INT NOT NULL, pool_cents BIGINT NOT NULL, remaining_cents BIGINT NOT NULL, max_winners INT NOT NULL, starts_at DATETIME(3) NOT NULL, ends_at DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, settled_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_events_status_window(status, starts_at, ends_at));
CREATE TABLE participations (id VARCHAR(64) PRIMARY KEY, event_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, sequence_no BIGINT NOT NULL, accepted_at DATETIME(3) NOT NULL, is_winner BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE KEY uq_event_user(event_id,user_id), UNIQUE KEY uq_event_sequence(event_id,sequence_no), FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE ledger_entries (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64), event_id VARCHAR(64), entry_type VARCHAR(40) NOT NULL, amount_cents BIGINT NOT NULL, status VARCHAR(24) NOT NULL, idempotency_key VARCHAR(128) NOT NULL UNIQUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(event_id) REFERENCES events(id));
CREATE TABLE audit_events (id VARCHAR(64) PRIMARY KEY, actor VARCHAR(64) NOT NULL, action VARCHAR(100) NOT NULL, target_id VARCHAR(64), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
